style.css:
/* Crimson Nocturne — WhatsApp Web */

:root {
  /* swap these colors whenever you like */
  --my-bg: #100b10;
  --my-panel: #1b1019;
  --my-burgundy: #481b30;
  --my-rose: #bd788e;
  --my-cream: #f1e4dc;
  --my-muted: #ad929e;
}

/* main page */
body {
  background: var(--my-bg) !important;
  color: var(--my-cream) !important;
  font-family: Georgia, serif !important;
}

/* links */
a {
  color: var(--my-rose) !important;
}

/* images */
img {
  border-radius: 12px;
}
